def title(v):
 if v['key']=='elements-nav-style-primary':return 'Navigazione con tipografia grande'
 if v['key']=='elements-nav-style-secondary-subtitles':return 'Navigazione con sottotitoli'
 if v['key']=='elements-overlay-slider-overlay-primary-cover-hover':return 'Overlay completo al passaggio del mouse'
 return EXACT.get(v['name'],v['name'].replace('uk ','UIkit ').capitalize())
def notes(v):
 s=v['anchor'];f=v['family'];out=[]
 rules=[('masonry','Altezze diverse con disposizione compatta.'),('filter','Navigazione per filtrare gli elementi.'),('thumbnav','Miniature per selezionare il contenuto.'),('dotnav','Puntini per selezionare il contenuto.'),('slidenav','Frecce per passare all’elemento precedente o successivo.'),('parallax','Movimento collegato allo scorrimento della pagina.'),('hover','Una parte del contenuto cambia o compare al passaggio del mouse.'),('lightbox','Apertura del media in una galleria modale.'),('sets','Gli elementi visibili avanzano insieme.'),('width-auto','Larghezza determinata dal contenuto.'),('image-left','Immagine affiancata a sinistra del testo.'),('image-right','Immagine affiancata a destra del testo.'),('image-top','Immagine sopra al contenuto.'),('image-between','Immagine inserita fra titolo e testo.'),('viewport-height','Altezza adattata alla finestra.'),('ken-burns','Zoom lento dell’immagine con dissolvenza.'),('offcanvas','Il contenuto si apre in un pannello laterale.'),('modal','Il collegamento apre una finestra modale.'),('leader','Una linea guida collega etichette e valori.'),('multiple-items','Consente più pannelli aperti insieme.'),('one-item','Mantiene un solo pannello aperto alla volta.'),('start-closed','I pannelli iniziano chiusi.'),('start-opened','La demo parte con contenuto già aperto.'),('image-orientation','Mantiene immagini con orientamenti diversi.'),('justify-columns','Le colonne si riallineano durante lo scroll.'),('clustering','Raggruppa i punti vicini della mappa.'),('on-click-loading','Carica il video dopo l’interazione.'),('border-circle','Ritaglio circolare.'),('border-pill','Ritaglio fortemente arrotondato.'),('border-rounded','Angoli arrotondati.'),('columns-thirds','Disposizione su tre colonne.'),('columns-halves','Disposizione su due colonne.')]
 for token,text in rules:
  if token in s:out.append(text)
 if f.endswith('slider') and ('center'==v['name'] or s.endswith('-center')):out.insert(0,'La slide attiva è centrata e lascia intravedere quelle adiacenti.')
 if not out:out=[('Esempio della sezione '+v['section']+'.') if v['group']=='widgetkit' else 'Variazione di '+v['name']+'.']
 return ' '.join(out[:3])

