_original_title=title
_original_notes=notes

def title(v):
 return DETAILS[v['name']][0] if v['name'] in DETAILS else _original_title(v)

def notes(v):
 if v['name'] in DETAILS:return DETAILS[v['name']][1]
 base=_original_notes(v)
 if not base.startswith('Variazione'):return base
 n=v['name']
 if 'gap' in n:
  return 'Spaziatura '+('assente' if 'none' in n else 'ridotta' if 'small' in n else 'ampia' if 'large' in n else 'media')+' fra gli elementi.'
 if 'divider' in n:return 'Linee divisorie separano le voci o le parti del contenuto.'
 if 'card' in n:return 'Il contenuto è raccolto in schede con un contenitore riconoscibile.'
 if 'animation' in n:return 'La demo usa la transizione '+n.replace('animation ','')+' fra le slide. Apri il collegamento per confrontarne il movimento.'
 if 'columns' in n and v['family']=='table':
  size='compatta' if 'small' in n else 'ampia' if 'large' in n else 'standard'
  layout='colonne a larghezza fissa' if 'fixed' in n else 'colonne aderenti al contenuto' if 'shrink' in n else ('due colonne espandibili' if 'two' in n else 'una colonna espandibile')
  return 'Tabella con spaziatura '+size+' e '+layout+'.'
 if 'shadow' in n:return 'Un’ombra separa visivamente l’immagine dallo sfondo; la demo confronta intensità e dimensione della decorazione.'
 if 'decoration' in n:return 'Una decorazione accompagna il titolo o il media: '+n.replace('title ','').replace('decoration ','').replace('box ','')+'.'
 if n.startswith(('style h','style 2xlarge','style xlarge','style large','style medium','style small')) and v['family']=='headline':return 'Dimensione tipografica '+n.replace('style ','')+' per il titolo, da distinguere dal suo livello semantico HTML.'
 if n.startswith('size ') or n in ('small','large'):return 'Variante di dimensione '+n.replace('size ','')+' del componente.'
 if n=='style primary' and v['family']=='nav':return 'Navigazione con tipografia più grande e maggiore evidenza delle singole voci.'
 if n=='style secondary subtitles' and v['family']=='nav':return 'Le voci della navigazione includono un sottotitolo descrittivo.'
 if n=='Esempio base':return 'Esempio introduttivo del componente nella demo ufficiale.'
 return base
